target.css:
:root {
  --ink: #20342c;
  --muted: #66766d;
  --paper: #fffdf4;
  --line: #d9dfcb;
  --moss: #315d4e;
  --moss-dark: #214438;
  --lime: #d8ed74;
  --lime-soft: #f1f8c9;
  --mint: #e2f0e6;
  --gold: #e9b94e;
}

.survey {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--moss);
  border-radius: 14px;
}

.survey__header,
.plot__heading,
.survey__footer,
.condition-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.survey__header {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow,
.label {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 4px 0 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 5px 8px;
  color: var(--moss-dark);
  background: var(--mint);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.status__dot {
  width: 7px;
  height: 7px;
  background: var(--moss);
  border-radius: 50%;
}

.survey__main {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr;
  gap: 14px;
  padding: 14px 0;
}

.plot {
  min-width: 0;
}

.plot__heading strong {
  display: block;
  margin-top: 3px;
  font-size: 15px;
}

.count {
  padding: 4px 7px;
  color: var(--moss-dark);
  background: var(--lime-soft);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
}

.plot__field {
  position: relative;
  height: 82px;
  margin-top: 10px;
  overflow: hidden;
  background: var(--moss-dark);
  border-radius: 9px 9px 4px 4px;
}

.plot__field::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 26px;
  content: "";
  background: var(--moss);
  border-radius: 55% 45% 0 0;
}

.spark {
  position: absolute;
  z-index: 1;
  width: 8px;
  height: 8px;
  background: var(--lime);
  border: 2px solid var(--gold);
  border-radius: 50%;
}

.spark--one { top: 18px; left: 17%; }
.spark--two { top: 39px; left: 34%; }
.spark--three { top: 13px; left: 48%; }
.spark--four { top: 31px; left: 63%; }
.spark--five { top: 21px; left: 78%; }
.spark--six { top: 45px; left: 88%; }

.plot__axis {
  display: flex;
  justify-content: space-between;
  padding-top: 5px;
  color: var(--muted);
  font-size: 10px;
}

.conditions {
  padding: 11px;
  background: var(--mint);
  border-radius: 9px;
}

.condition-list {
  display: grid;
  gap: 7px;
  padding: 0;
  margin: 9px 0 0;
  list-style: none;
}

.condition-list li {
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

.condition-list li:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.condition-list strong {
  color: var(--ink);
  font-size: 12px;
}

.survey__footer {
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.survey__footer p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.pin {
  color: var(--gold);
  font-size: 14px;
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--moss);
  border: 1px solid var(--moss);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

